hints.content:
Full working solution:

function cafeRushWindow(customers, windowSize) {
  if (customers.length === 0) return 0;

  if (windowSize >= customers.length) {
    return customers.reduce((sum, value) => sum + value, 0);
  }

  let current = 0;

  for (let i = 0; i < windowSize; i++) {
    current += customers[i];
  }

  let best = current;

  for (let right = windowSize; right < customers.length; right++) {
    current += customers[right];
    current -= customers[right - windowSize];
    best = Math.max(best, current);
  }

  return best;
}

Time complexity: O(n), where n is customers.length.
Space complexity: O(1).

