Full working solution:

function kPopLightstickWave(colors, maxColors) {
  if (maxColors === 0) return 0;

  const counts = new Map();
  let left = 0;
  let best = 0;

  for (let right = 0; right < colors.length; right++) {
    const color = colors[right];
    counts.set(color, (counts.get(color) || 0) + 1);

    while (counts.size > maxColors) {
      const leftColor = colors[left];
      counts.set(leftColor, counts.get(leftColor) - 1);

      if (counts.get(leftColor) === 0) {
        counts.delete(leftColor);
      }

      left++;
    }

    best = Math.max(best, right - left + 1);
  }

  return best;
}

Time complexity: O(n), where n is colors.length.
Space complexity: O(k), where k is the number of colors in the current window.

