  const reverse = (arr, start, end) => {
    while (start < end) {
      [arr[start], arr[end]] = [arr[end], arr[start]];
      start++;
      end--;
    }
  };
  reverse(line, 0, line.length - 1);
  reverse(line, 0, k - 1);
  reverse(line, k, line.length - 1);
}

