Full working solution in JavaScript:

function tacoTruckRushWindow(sales, windowSize) {
  if (sales.length === 0) return 0;

  if (windowSize >= sales.length) {
    return sales.reduce((sum, value) => sum + value, 0);
  }

  let current = 0;

  for (let i = 0; i < windowSize; i++) {
    current += sales[i];
  }

  let best = current;

  for (let right = windowSize; right < sales.length; right++) {
    current += sales[right];
    current -= sales[right - windowSize];
    best = Math.max(best, current);
  }

  return best;
}

Time complexity: O(n), where n is sales.length.
Space complexity: O(1).

