function paellaPanCapacity(ingredients, pans) {
  let low = Math.max(...ingredients);
  let high = ingredients.reduce((sum, value) => sum + value, 0);

  function canCook(limit) {
    let usedPans = 1;
    let current = 0;

    for (const amount of ingredients) {
      if (current + amount > limit) {
        usedPans++;
        current = amount;
      } else {
        current += amount;
      }
    }

    return usedPans <= pans;
  }

  while (low < high) {
    const mid = Math.floor((low + high) / 2);

    if (canCook(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }

  return low;
}

Time complexity: O(n log S), where n is ingredients.length and S is the sum range.
Space complexity: O(1).

