function marketStreetAromaWave(aromas, maxAromas) {
  if (maxAromas === 0) return 0;

  const counts = new Map();
  let left = 0;
  let best = 0;

  for (let right = 0; right < aromas.length; right++) {
    const aroma = aromas[right];
    counts.set(aroma, (counts.get(aroma) || 0) + 1);

