function rockConcertDecibelBalance(powers, k) {
  let left = Math.max(...powers);
  let right = powers.reduce((a, b) => a + b, 0);

  function canSplit(maxSum) {
    let count = 1, current = 0;
    for (let p of powers) {
      if (current + p > maxSum) {
        count++;
        current = p;
      } else {
        current += p;
      }
    }
    return count <= k;
  }

  while (left < right) {
    let mid = Math.floor((left + right) / 2);
    if (canSplit(mid)) right = mid;
    else left = mid + 1;
  }
  return left;
}

Time complexity: O(n * log(sum(powers))).
Space complexity: O(1).

