function archipelagoBridgeNetwork(n, edges) {
  if (n === 1) return 0;
  edges.sort((a, b) => a[2] - b[2]);
  const parent = Array.from({length: n}, (_, i) => i);
  function find(i) {
    if (parent[i] === i) return i;
    return parent[i] = find(parent[i]);
  }
  function union(i, j) {
    const rootI = find(i), rootJ = find(j);
    if (rootI !== rootJ) {
      parent[rootI] = rootJ;
      return true;
    }
    return false;
  }
  let totalCost = 0, count = 0;
  for (let [u, v, cost] of edges) {
    if (union(u, v)) {
      totalCost += cost;
      count++;
    }
  }
  return count === n - 1 ? totalCost : -1;
}

Time complexity: O(E log E).
Space complexity: O(N).

