function travelRouteCycleDetection(routes) {
  let graph = new Map();
  for (let [u,v] of routes) {
    if (!graph.has(u)) graph.set(u, []);
    graph.get(u).push(v);
  }
  let visiting = new Set();
  function dfs(node) {
    if (visiting.has(node)) return true;
    visiting.add(node);
    if (graph.has(node)) {
      for (let nei of graph.get(node)) {
        if (dfs(nei)) return true;
      }
    }
    visiting.delete(node);
    return false;
  }
  for (let city of graph.keys()) {
    if (dfs(city)) return true;
  }
  return false;
}

