function koiFeedingBinarySearch(piles, h) {
  let low = 1, high = Math.max(...piles);
  while (low < high) {
    let mid = Math.floor((low + high) / 2);
    let hours = 0;
    for (let p of piles) hours += Math.ceil(p / mid);
    if (hours <= h) high = mid;
    else low = mid + 1;
  }
  return low;
}

