function dragonTreasureLongestPath(grid) {
  if (!grid.length) return 0;
  let m = grid.length, n = grid[0].length;
  let memo = Array.from({length:m},()=>Array(n).fill(0));
  function dfs(i,j) {
    if (memo[i][j]) return memo[i][j];
    let max = 1;
    const dirs = [[0,1],[1,0],[0,-1],[-1,0]];
    for (let [dx,dy] of dirs) {
      let ni = i+dx, nj = j+dy;
      if (ni>=0 && ni<m && nj>=0 && nj<n && grid[ni][nj] > grid[i][j]) {
        max = Math.max(max, 1 + dfs(ni,nj));
      }
    }
    memo[i][j] = max;
    return max;
  }
  let ans = 0;
  for (let i=0; i<m; i++) for (let j=0; j<n; j++) ans = Math.max(ans, dfs(i,j));
  return ans;
}

Time complexity: O(m*n), Space complexity: O(m*n)

