function ancientCityConnectedProvinces(isConnected) {
  let n = isConnected.length;
  let parent = Array.from({length: n}, (_,i)=>i);
  function find(x) {
    if (parent[x] !== x) parent[x] = find(parent[x]);
    return parent[x];
  }
  function union(x,y) {
    let px = find(x), py = find(y);
    if (px !== py) parent[px] = py;
  }
  for (let i = 0; i < n; i++) {
    for (let j = i+1; j < n; j++) {
      if (isConnected[i][j]) union(i,j);
    }
  }
  let provinces = new Set();
  for (let i = 0; i < n; i++) provinces.add(find(i));
  return provinces.size;
}

