function festivalScheduleMerge(schedules) {
  let heap = [];
  for (let i = 0; i < schedules.length; i++) {
    if (schedules[i].length) heap.push([schedules[i][0], i, 0]);
  }
  heap.sort((a,b)=>a[0]-b[0]);
  let result = [];
  while (heap.length) {
    let [val, listIdx, elemIdx] = heap.shift();
    result.push(val);
    if (elemIdx + 1 < schedules[listIdx].length) {
      let nextVal = schedules[listIdx][elemIdx+1];
      heap.push([nextVal, listIdx, elemIdx+1]);
      heap.sort((a,b)=>a[0]-b[0]);
    }
  }
  return result;
}

Time complexity: O(N log k), Space complexity: O(k)

