function koiPondMedianStream(sizes) {
  let maxHeap = [], minHeap = [], result = [];
  for (let num of sizes) {
    if (!maxHeap.length || num <= maxHeap[0]) maxHeap.unshift(num);
    else minHeap.push(num);
    if (maxHeap.length > minHeap.length + 1) minHeap.unshift(maxHeap.shift());
    else if (minHeap.length > maxHeap.length) maxHeap.unshift(minHeap.shift());
    maxHeap.sort((a,b)=>b-a); minHeap.sort((a,b)=>a-b);
    if (maxHeap.length === minHeap.length) result.push((maxHeap[0] + minHeap[0])/2);
    else result.push(maxHeap[0]);
  }
  return result;
}

