function tokyoRamenRushMonitor(orders, k) {
  const q = [], res = [];
  for (let i = 0; i < orders.length; i++) {
    while (q.length && orders[q[q.length-1]] <= orders[i]) q.pop();
    q.push(i);
    if (q[0] === i - k) q.shift();
    if (i >= k - 1) res.push(orders[q[0]]);
  }
  return res;
}

Time complexity: O(n)
Space complexity: O(k)

