function amazonRainforestConnectivity(n, connections) {
  const p = Array.from({length:n}, (_,i)=>i); let c = n;
  const find = (i) => p[i] === i ? i : p[i] = find(p[i]);
  for (let [u,v] of connections) {
    let rootU = find(u), rootV = find(v);
    if (rootU !== rootV) { p[rootU] = rootV; c--; }
  }
  return c - 1;
}

Time complexity: O(N + E alpha(N))
Space complexity: O(N)

