function rosettaStonePrefixSearch(words, prefix) {
  const root = {};
  for (let w of words) {
    let node = root;
    for (let c of w) { if (!node[c]) node[c] = {}; node = node[c]; }
  }
  let cur = root;
  for (let c of prefix) { if (!cur[c]) return false; cur = cur[c]; }
  return true;
}

Time complexity: O(N) build, O(P) search
Space complexity: O(N)
